{"hypotheses": [
  {
    "name": "Supply Chain Resilience Premium",
    "mechanism": "Firms with strong customer and supplier momentum (iomom_cust, iomom_supp) and robust order backlog growth (OrderBacklogChg) are positioned to benefit disproportionately from resilient supply chains, especially when macro uncertainty is elevated. A composite of these signals identifies firms best able to flexibly monetize demand shocks, capturing cross-sectional return opportunities missed by each input alone.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "iomom_supp"},
        {"weight": 1.0, "primitive": "OrderBacklogChg"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OrderBacklogChg", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Governance-Contrarian Premium",
    "mechanism": "Firms with strong governance (Governance) yet temporarily depressed momentum (MomOffSeason) offer mean-reverting opportunities as good stewards recover from overdone selloffs. Combining these two signals inverts the typical pattern, exploiting the differential between realized governance quality and mispriced recent returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 1.0, "primitive": "MomOffSeason"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "Governance", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Innovation Crowding Anomaly",
    "mechanism": "Firms with high R&D expenditures (RD) but low analyst coverage (ChNAnalyst) and high patent generation (PatentsRD) escape the usual return drag from analyst over-crowding. The composite isolates firms whose innovation is underappreciated by the sell-side, capturing informational inefficiencies.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": -1.0, "primitive": "ChNAnalyst"},
        {"weight": 0.5, "primitive": "PatentsRD"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "RD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 42
  },
  {
    "name": "Short-Interest Cash Trap",
    "mechanism": "Stocks with high short interest (ShortInterest) and poor cash productivity (CashProd), but positive earnings consistency (EarningsConsistency), are often over-shorted due to temporary cash flow issues despite robust earnings. The composite exploits forced liquidations that misjudge sustainable earnings quality.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShortInterest"},
        {"weight": -1.0, "primitive": "CashProd"},
        {"weight": 0.5, "primitive": "EarningsConsistency"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Real Asset Scarcity Premium",
    "mechanism": "Firms with high real estate holdings (realestate), high tangibility (tang), and positive payout yield (PayoutYield) are positioned to benefit from real asset scarcity, especially when interest rates are low (TERM_SPREAD_NEGATIVE). This composite captures a unique cross-section of asset-based mispricing.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "realestate"},
        {"weight": 0.5, "primitive": "tang"},
        {"weight": 1.0, "primitive": "PayoutYield"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Credit Dislocation Reversal",
    "mechanism": "Stocks experiencing credit rating downgrades (CredRatDG) but simultaneously increasing R&D capital to assets (RDcap) and showing positive abnormal accruals (AbnormalAccruals) often recover as credit markets over-react to short-term distress, especially when equities have positive momentum.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CredRatDG"},
        {"weight": 0.5, "primitive": "RDcap"},
        {"weight": 0.5, "primitive": "AbnormalAccruals"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "CredRatDG", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Organizational Capital Restructuring Edge",
    "mechanism": "Firms with rising organizational capital (OrgCap), high deferred revenue (DelDRC), and declining analyst optimism (AOP) are overlooked during early-stage restructurings. The composite captures market underreaction to intangible investment and booking changes preceding visible turnarounds.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "AOP"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Dealer Liquidity Withdrawal",
    "mechanism": "Stocks exposed to high Pastor-Stambaugh liquidity beta (BetaLiquidityPS) and increasing bid-ask spreads (BidAskSpread), but with falling share turnover volatility (std_turn), become vulnerable when dealers withdraw liquidity. This composite identifies securities whose price formation is most impaired by exogenous shocks to liquidity supply.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BetaLiquidityPS"},
        {"weight": 1.0, "primitive": "BidAskSpread"},
        {"weight": -1.0, "primitive": "std_turn"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "BetaLiquidityPS", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 12
  }
]}
